import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useOSStore } from '../store/useOSStore';
import {
  Sparkles,
  Zap,
  Radio,
  ChevronLeft,
  Play,
  Pause,
  Shield,
  CheckCircle2,
  Lock,
  Layers,
  Flame,
  Activity,
  Eye,
  Key,
  Link as LinkIcon,
  ShieldAlert,
  Maximize2,
  Minimize2
} from 'lucide-react';

export default function PhoneWidget() {
  const [deviceMode, setDeviceMode] = useState('pane'); // 'pane' | 'tablet'
  const [screenApp, setScreenApp] = useState('home'); // 'home' | 'comms' | 'passport' | 'quests' | 'spellforge' | 'music' | 'camera' | 'status'
  const [isPlaying, setIsPlaying] = useState(false);
  const [activeCommsContact, setActiveCommsContact] = useState('Dr. Maelis Voss');
  const [spellSelectedElement, setSpellSelectedElement] = useState(null);
  const [spellSelectedUtility, setSpellSelectedUtility] = useState(null);
  const [spellResult, setSpellResult] = useState('');
  const [rippleKey, setRippleKey] = useState(0);

  const [npcMessages, setNpcMessages] = useState({
    'Dr. Maelis Voss': [
      { id: 1, text: 'Student, verify your Aethercore frequency before entry into Lab 4.', time: '09:12' },
      { id: 2, text: 'The Lightborn aura logic indicates a minor resonance shift in your record.', time: '09:15' },
    ],
    'Dean Cassian Rook': [
      { id: 3, text: 'Welcome to Cyacademy. Your provisional registration is active.', time: '08:30' },
      { id: 4, text: 'Remember to complete your daily Aura Passport check-in on the Bulletin Node.', time: '08:35' },
    ],
    'Agent Mara Quell': [
      { id: 5, text: 'DGA Field Alert: Patrol routes in Sector 7 are under heightened monitoring.', time: '09:00' },
      { id: 6, text: 'Keep your netrunner tools ready in case of PRISM corruption spikes.', time: '09:05' },
    ],
    'Archivist Selene': [
      { id: 7, text: 'Purge-era genealogy records have been logged in the restricted archives.', time: '08:45' },
    ],
  });
  const [chatInput, setChatInput] = useState('');

  const player = useOSStore((s) => s.gameplay.player);
  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);
  const purgePrismCorruption = useOSStore((s) => s.purgePrismCorruption);
  const prismCorruptionLevel = useOSStore((s) => s.gameplay.prismCorruptionLevel);

  const triggerRuneApp = (appName) => {
    setRippleKey((prev) => prev + 1);
    setScreenApp(appName);
  };

  const handleSendNpcMessage = (e) => {
    if (e.key !== 'Enter' || !chatInput.trim()) return;
    setNpcMessages((prev) => ({
      ...prev,
      [activeCommsContact]: [
        ...(prev[activeCommsContact] || []),
        { id: Date.now(), text: chatInput.trim(), time: 'Just now', isPlayer: true },
      ],
    }));
    setChatInput('');
  };

  const handleSynthesizeSpell = () => {
    if (!spellSelectedElement || !spellSelectedUtility) {
      setSpellResult('⚠️ Select 1 Element & 1 Utility sigil.');
      return;
    }
    const spellName = `${spellSelectedElement} ${spellSelectedUtility}`;
    addCredits(75);
    addXP(40);
    purgePrismCorruption(1.5);
    setSpellResult(`✨ Synthesized [${spellName}]! +75 ₡, +40 XP, PRISM Corruption Reduced.`);
    setSpellSelectedElement(null);
    setSpellSelectedUtility(null);
  };

  return (
    <motion.div
      layout
      transition={{ type: 'spring', stiffness: 280, damping: 28 }}
      className={`relative select-none overflow-hidden transition-all duration-500 rounded-2xl border-2 shadow-[0_0_40px_rgba(77,243,255,0.25)] ${
        prismCorruptionLevel > 10
          ? 'border-pink-500/60 bg-slate-950/90 text-white'
          : 'border-cyan-400/40 bg-slate-950/85 text-white backdrop-blur-2xl'
      } ${
        deviceMode === 'tablet'
          ? 'w-[620px] h-[520px]'
          : 'w-[260px] h-[480px]'
      }`}
    >
      {/* ------------------------------------------------------------------ */}
      {/* BACKGROUND AETHER SHIMMER & PRISM CORRUPTION FRACTURE VEINS         */}
      {/* ------------------------------------------------------------------ */}
      <div className="absolute inset-0 bg-gradient-to-br from-cyan-500/10 via-purple-500/5 to-pink-500/10 pointer-events-none" />

      {/* PRISM Glitch Static Veins when Corruption is High */}
      {prismCorruptionLevel > 10 && (
        <div className="absolute inset-0 bg-[radial-gradient(#FF007A_1px,transparent_1px)] [background-size:16px_16px] opacity-20 pointer-events-none animate-pulse" />
      )}

      {/* ------------------------------------------------------------------ */}
      {/* PULSING EDGE VEIL GLYPHS ALONG THE GLASS SLAB EDGE                  */}
      {/* ------------------------------------------------------------------ */}
      <div className="absolute top-2 left-3 right-3 flex justify-between items-center text-[9px] font-mono text-cyan-400/70 pointer-events-none z-30">
        <span className="animate-pulse">✦ ◈ ⚜</span>
        <span className="tracking-widest text-[8px] text-cyan-300/90 font-bold">AETHERIC HOLO-PANE</span>
        <span className="animate-pulse">⚜ ◈ ✦</span>
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* HEADER CONTROL BAR WITH VEIL-FOLD TABLET EXPANSION BUTTON           */}
      {/* ------------------------------------------------------------------ */}
      <div className="relative z-30 pt-6 px-4 pb-2 flex items-center justify-between border-b border-cyan-500/20 bg-cyan-950/30">
        <div className="flex items-center gap-1.5 text-[10px] font-mono font-bold text-cyan-300">
          <Radio size={13} className="animate-pulse text-cyan-400" />
          <span>{deviceMode === 'tablet' ? 'AETHER TABLET MATRIX' : 'HOLO COMM PANE'}</span>
        </div>

        {/* Veil-Fold Device Expansion Toggle */}
        <button
          onClick={() => setDeviceMode((prev) => (prev === 'pane' ? 'tablet' : 'pane'))}
          className="flex items-center gap-1.5 rounded-lg border border-cyan-400/40 bg-cyan-500/10 hover:bg-cyan-500/30 px-2.5 py-1 text-[10px] font-bold text-cyan-200 hover:text-white transition shadow-[0_0_10px_rgba(77,243,255,0.3)]"
          title={deviceMode === 'pane' ? 'Veil-Fold Expand to Aether Tablet' : 'Return to Holo-Pane'}
        >
          {deviceMode === 'pane' ? (
            <>
              <Maximize2 size={12} className="text-cyan-400" /> ✦ Veil-Fold Expand
            </>
          ) : (
            <>
              <Minimize2 size={12} className="text-pink-400" /> Holo-Pane 📱
            </>
          )}
        </button>
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* DISPLAY CONTENT AREA (HOLO-PANE SINGLE VS TABLET MULTI-PANE)        */}
      {/* ------------------------------------------------------------------ */}
      <div className="relative z-20 h-[calc(100%-42px)] p-3.5 flex flex-col justify-between overflow-hidden">
        {/* Veil Breach Ripple Effect on App Activation */}
        <AnimatePresence>
          <motion.div
            key={rippleKey}
            initial={{ scale: 0.1, opacity: 0.8 }}
            animate={{ scale: 2.5, opacity: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.6, ease: 'easeOut' }}
            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 rounded-full border-2 border-cyan-400/60 bg-cyan-400/10 pointer-events-none z-10"
          />
        </AnimatePresence>

        {/* ================================================================== */}
        {/* DEVICE MODE 1: HOLO-PANE SINGLE DISPLAY MODE                        */}
        {/* ================================================================== */}
        {deviceMode === 'pane' && (
          <div className="h-full flex flex-col justify-between">
            {/* Top Status Badge */}
            <div className="flex justify-between items-center text-[10px] font-mono text-cyan-300/80 px-1 border-b border-cyan-500/20 pb-1.5">
              <span>AURELINE_MESH</span>
              <span className="font-bold text-emerald-400">⚡ 100% SYNC</span>
            </div>

            {/* HOME SCREEN SIGIL RUNES GRID */}
            {screenApp === 'home' && (
              <div className="space-y-4 my-auto">
                {/* Player Identity Badge */}
                <button
                  onClick={() => triggerRuneApp('status')}
                  className="w-full rounded-xl border border-cyan-400/30 bg-cyan-950/40 p-2.5 flex items-center justify-between hover:border-cyan-300 hover:shadow-[0_0_15px_rgba(77,243,255,0.4)] transition"
                >
                  <div className="flex items-center gap-2.5">
                    <div className="w-8 h-8 rounded-lg bg-purple-500/20 border border-purple-300/50 flex items-center justify-center font-bold text-xs text-purple-200">
                      P
                    </div>
                    <div className="text-left font-mono">
                      <div className="text-[11px] font-bold text-white leading-none">PLAYERNAME</div>
                      <div className="text-[9px] text-cyan-300 mt-1">Level {player.level} • ₡{player.credits}</div>
                    </div>
                  </div>
                  <Shield size={16} className="text-emerald-400" />
                </button>

                {/* SIGIL-BASED GLYPH RUNES GRID */}
                <div className="grid grid-cols-3 gap-3">
                  {/* Comms → Linked Circuit Glyph */}
                  <button
                    onClick={() => triggerRuneApp('comms')}
                    className="flex flex-col items-center group"
                    title="Comms — Linked Circuit Glyph"
                  >
                    <div className="h-12 w-12 rounded-xl bg-slate-900/90 border border-cyan-400/40 group-hover:border-cyan-300 group-hover:shadow-[0_0_20px_rgba(77,243,255,0.6)] group-hover:bg-cyan-500/20 flex items-center justify-center text-cyan-300 transition duration-200">
                      <LinkIcon size={22} className="group-hover:scale-110 transition" />
                    </div>
                    <span className="text-[9px] font-mono font-bold text-cyan-200 mt-1.5">Comms</span>
                  </button>

                  {/* SpellForge → Forge Rune with Flux Ring */}
                  <button
                    onClick={() => triggerRuneApp('spellforge')}
                    className="flex flex-col items-center group"
                    title="SpellForge — Forge Rune with Flux Ring"
                  >
                    <div className="h-12 w-12 rounded-xl bg-slate-900/90 border border-violet-400/40 group-hover:border-violet-300 group-hover:shadow-[0_0_20px_rgba(199,124,255,0.6)] group-hover:bg-violet-500/20 flex items-center justify-center text-violet-300 transition duration-200">
                      <Flame size={22} className="group-hover:scale-110 transition" />
                    </div>
                    <span className="text-[9px] font-mono font-bold text-violet-200 mt-1.5">SpellForge</span>
                  </button>

                  {/* Passport → Celestial Key Symbol */}
                  <button
                    onClick={() => triggerRuneApp('passport')}
                    className="flex flex-col items-center group"
                    title="Passport — Celestial Key Symbol"
                  >
                    <div className="h-12 w-12 rounded-xl bg-slate-900/90 border border-amber-400/40 group-hover:border-amber-300 group-hover:shadow-[0_0_20px_rgba(255,216,107,0.6)] group-hover:bg-amber-500/20 flex items-center justify-center text-amber-300 transition duration-200">
                      <Key size={22} className="group-hover:scale-110 transition" />
                    </div>
                    <span className="text-[9px] font-mono font-bold text-amber-200 mt-1.5">Passport</span>
                  </button>

                  {/* Music → Waveform Halo */}
                  <button
                    onClick={() => triggerRuneApp('music')}
                    className="flex flex-col items-center group"
                    title="Music — Waveform Halo"
                  >
                    <div className="h-12 w-12 rounded-xl bg-slate-900/90 border border-emerald-400/40 group-hover:border-emerald-300 group-hover:shadow-[0_0_20px_rgba(52,211,153,0.6)] group-hover:bg-emerald-500/20 flex items-center justify-center text-emerald-300 transition duration-200">
                      <Activity size={22} className="group-hover:scale-110 transition" />
                    </div>
                    <span className="text-[9px] font-mono font-bold text-emerald-200 mt-1.5">Aether Radio</span>
                  </button>

                  {/* Camera → Eye-Lens Glyph */}
                  <button
                    onClick={() => triggerRuneApp('camera')}
                    className="flex flex-col items-center group"
                    title="Camera — Eye-Lens Glyph"
                  >
                    <div className="h-12 w-12 rounded-xl bg-slate-900/90 border border-pink-400/40 group-hover:border-pink-300 group-hover:shadow-[0_0_20px_rgba(244,114,182,0.6)] group-hover:bg-pink-500/20 flex items-center justify-center text-pink-300 transition duration-200">
                      <Eye size={22} className="group-hover:scale-110 transition" />
                    </div>
                    <span className="text-[9px] font-mono font-bold text-pink-200 mt-1.5">Lens Eye</span>
                  </button>

                  {/* Tasks → Shield Matrix Glyph */}
                  <button
                    onClick={() => triggerRuneApp('quests')}
                    className="flex flex-col items-center group"
                    title="Tasks — Shield Matrix Glyph"
                  >
                    <div className="h-12 w-12 rounded-xl bg-slate-900/90 border border-purple-400/40 group-hover:border-purple-300 group-hover:shadow-[0_0_20px_rgba(192,132,252,0.6)] group-hover:bg-purple-500/20 flex items-center justify-center text-purple-300 transition duration-200">
                      <ShieldAlert size={22} className="group-hover:scale-110 transition" />
                    </div>
                    <span className="text-[9px] font-mono font-bold text-purple-200 mt-1.5">DGA Tasks</span>
                  </button>
                </div>
              </div>
            )}

            {/* ON-DEVICE APP VIEWS */}
            {screenApp === 'comms' && (
              <div className="h-full flex flex-col justify-between bg-slate-900/80 rounded-xl p-3 border border-cyan-400/30 text-xs">
                <div className="flex items-center justify-between border-b border-cyan-400/30 pb-1.5">
                  <button onClick={() => setScreenApp('home')} className="text-cyan-300 hover:text-white flex items-center gap-1 font-mono text-[10px]">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="font-bold font-mono text-cyan-300 text-[10px]">CYCADEMY MESSENGER</span>
                  <LinkIcon size={14} className="text-cyan-400" />
                </div>

                <div className="flex gap-1 overflow-x-auto py-1 border-b border-white/10">
                  {Object.keys(npcMessages).map((npc) => (
                    <button
                      key={npc}
                      onClick={() => setActiveCommsContact(npc)}
                      className={`px-2 py-0.5 rounded-full text-[9px] whitespace-nowrap transition font-mono ${
                        activeCommsContact === npc
                          ? 'bg-cyan-500 text-slate-950 font-bold'
                          : 'bg-white/10 text-white/60 hover:bg-white/20'
                      }`}
                    >
                      {npc}
                    </button>
                  ))}
                </div>

                <div className="flex-1 overflow-auto space-y-2 my-2 pr-1">
                  {(npcMessages[activeCommsContact] || []).map((msg) => (
                    <div
                      key={msg.id}
                      className={`rounded-lg p-2 border space-y-0.5 ${
                        msg.isPlayer
                          ? 'bg-purple-950/60 border-purple-400/40 ml-4'
                          : 'bg-slate-950/80 border-cyan-400/30 mr-4'
                      }`}
                    >
                      <div className="flex justify-between items-center text-[9px] font-mono">
                        <span className="font-bold text-cyan-300">{msg.isPlayer ? 'PLAYERNAME' : activeCommsContact}</span>
                        <span className="text-white/40">{msg.time}</span>
                      </div>
                      <div className="text-white/90 text-[10px]">{msg.text}</div>
                    </div>
                  ))}
                </div>

                <input
                  type="text"
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  onKeyDown={handleSendNpcMessage}
                  placeholder={`Message ${activeCommsContact}...`}
                  className="w-full rounded-lg border border-cyan-400/40 bg-black/60 px-2.5 py-1.5 text-xs text-white outline-none focus:border-cyan-300 font-mono"
                />
              </div>
            )}

            {screenApp === 'passport' && (
              <div className="h-full flex flex-col justify-between bg-slate-900/80 rounded-xl p-3 border border-amber-400/30 text-xs">
                <div className="flex items-center justify-between border-b border-amber-400/30 pb-1.5 font-mono">
                  <button onClick={() => setScreenApp('home')} className="text-amber-300 hover:text-white flex items-center gap-1 text-[10px]">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="font-bold text-amber-300 text-[10px]">CELESTIAL PASSPORT</span>
                  <Key size={14} className="text-amber-400" />
                </div>

                <div className="rounded-xl border border-amber-400/40 bg-gradient-to-br from-purple-950/70 to-slate-950/90 p-3 space-y-2 text-[10px] font-mono">
                  <div className="flex justify-between border-b border-white/10 pb-1">
                    <span className="text-white/60">Student:</span>
                    <span className="font-bold text-white">PLAYERNAME</span>
                  </div>
                  <div className="flex justify-between border-b border-white/10 pb-1">
                    <span className="text-white/60">Aura Serial:</span>
                    <span className="font-mono text-cyan-300">CY-9021-X9</span>
                  </div>
                  <div className="flex justify-between border-b border-white/10 pb-1">
                    <span className="text-white/60">Level / XP:</span>
                    <span className="font-bold text-emerald-400">Level {player.level} ({player.xp} XP)</span>
                  </div>
                  <div className="flex justify-between border-b border-white/10 pb-1">
                    <span className="text-white/60">Credits:</span>
                    <span className="font-bold text-emerald-400">₡{player.credits}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-white/60">Status:</span>
                    <span className="font-bold text-emerald-400 flex items-center gap-1">
                      <CheckCircle2 size={12} /> VERIFIED
                    </span>
                  </div>
                </div>

                <div className="rounded-lg bg-white p-2 text-center font-mono text-[9px] text-black font-bold tracking-widest border border-amber-300">
                  ||| | |||| ||| |||| | ||||| CY-9021
                </div>
              </div>
            )}

            {screenApp === 'spellforge' && (
              <div className="h-full flex flex-col justify-between bg-slate-900/80 rounded-xl p-3 border border-violet-400/30 text-xs">
                <div className="flex items-center justify-between border-b border-violet-400/30 pb-1.5 font-mono">
                  <button onClick={() => setScreenApp('home')} className="text-violet-300 hover:text-white flex items-center gap-1 text-[10px]">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="font-bold text-violet-300 text-[10px]">SPELLFORGE RUNE SYNTH</span>
                  <Flame size={14} className="text-violet-400" />
                </div>

                <div className="space-y-2 my-1 text-[10px] font-mono">
                  <div>
                    <div className="text-white/50 mb-1">Select Element:</div>
                    <div className="grid grid-cols-3 gap-1">
                      {['Firewall', 'Cryo', 'Encryption'].map((el) => (
                        <button
                          key={el}
                          onClick={() => setSpellSelectedElement(el)}
                          className={`p-1.5 rounded-lg border font-semibold transition ${
                            spellSelectedElement === el
                              ? 'border-violet-400 bg-violet-500/30 text-white'
                              : 'border-white/10 bg-white/5 text-white/70 hover:bg-white/10'
                          }`}
                        >
                          {el}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div>
                    <div className="text-white/50 mb-1">Select Utility:</div>
                    <div className="grid grid-cols-3 gap-1">
                      {['Routing', 'Anchor', 'Pulse'].map((ut) => (
                        <button
                          key={ut}
                          onClick={() => setSpellSelectedUtility(ut)}
                          className={`p-1.5 rounded-lg border font-semibold transition ${
                            spellSelectedUtility === ut
                              ? 'border-cyan-400 bg-cyan-500/30 text-white'
                              : 'border-white/10 bg-white/5 text-white/70 hover:bg-white/10'
                          }`}
                        >
                          {ut}
                        </button>
                      ))}
                    </div>
                  </div>

                  {spellResult && (
                    <div className="rounded-lg bg-slate-950 border border-violet-400/40 p-2 text-violet-300 font-mono text-[9px] animate-fade-in">
                      {spellResult}
                    </div>
                  )}
                </div>

                <button
                  onClick={handleSynthesizeSpell}
                  className="w-full rounded-lg border border-violet-400 bg-violet-500/20 py-2 font-bold font-mono text-violet-300 hover:bg-violet-500/40 transition shadow text-xs flex items-center justify-center gap-1.5"
                >
                  <Sparkles size={14} className="text-violet-400" /> [ SYNTHESIZE SPELL ]
                </button>
              </div>
            )}

            {screenApp === 'music' && (
              <div className="space-y-3 bg-slate-900/80 rounded-xl p-3 border border-emerald-400/30 text-center">
                <div className="flex items-center justify-between font-mono">
                  <button onClick={() => setScreenApp('home')} className="text-emerald-300 hover:text-white text-[10px] flex items-center gap-1">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="text-[10px] font-bold text-emerald-300">WAVEFORM HALO RADIO</span>
                  <div className="w-4" />
                </div>

                <div className="w-16 h-16 mx-auto rounded-xl bg-emerald-950/80 border border-emerald-400/40 flex items-center justify-center text-emerald-300">
                  <Activity size={28} className={isPlaying ? 'animate-pulse' : ''} />
                </div>

                <div className="font-mono space-y-0.5">
                  <div className="text-[11px] font-bold text-white">Aureline Sprawl Wave #04</div>
                  <div className="text-[9px] text-emerald-400/80">Cyacademy Student Mesh</div>
                </div>

                <button
                  onClick={() => setIsPlaying((prev) => !prev)}
                  className="w-10 h-10 mx-auto rounded-full bg-emerald-400 text-slate-950 flex items-center justify-center font-bold hover:scale-105 transition shadow-[0_0_15px_rgba(52,211,153,0.6)]"
                >
                  {isPlaying ? <Pause size={18} /> : <Play size={18} className="ml-0.5" />}
                </button>
              </div>
            )}

            {screenApp === 'camera' && (
              <div className="space-y-2 bg-slate-900/80 rounded-xl p-3 border border-pink-400/30 text-center font-mono">
                <div className="flex items-center justify-between">
                  <button onClick={() => setScreenApp('home')} className="text-pink-300 hover:text-white text-[10px] flex items-center gap-1">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="text-[10px] font-bold text-pink-300">EYE-LENS LENS</span>
                  <div className="w-4" />
                </div>

                <div className="relative w-full h-28 rounded-xl border border-dashed border-pink-400/60 bg-black/60 overflow-hidden flex items-center justify-center">
                  <div className="absolute inset-2 border border-pink-400/30 rounded-lg pointer-events-none" />
                  <span className="text-[10px] text-pink-300 font-mono">EYE-LENS: SCANNING</span>
                </div>

                <button
                  onClick={() => alert('📷 Snapshot captured to Files archive!')}
                  className="w-8 h-8 mx-auto rounded-full border-2 border-pink-300 bg-pink-500/30 hover:bg-pink-500/50 transition shadow-[0_0_15px_rgba(244,114,182,0.6)]"
                />
              </div>
            )}

            {screenApp === 'quests' && (
              <div className="h-full flex flex-col justify-between bg-slate-900/80 rounded-xl p-3 border border-purple-400/30 text-xs font-mono">
                <div className="flex items-center justify-between border-b border-purple-400/30 pb-1.5">
                  <button onClick={() => setScreenApp('home')} className="text-purple-300 hover:text-white text-[10px] flex items-center gap-1">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="font-bold text-purple-300 text-[10px]">SHIELD MATRIX TASKS</span>
                  <ShieldAlert size={14} className="text-purple-400" />
                </div>

                <div className="space-y-2 my-1 overflow-auto text-[10px]">
                  <div className="rounded-xl border border-purple-400/30 bg-purple-950/40 p-2 space-y-1">
                    <div className="font-bold text-purple-300 flex items-center gap-1">
                      <Zap size={12} className="text-purple-400" /> Sector 7 Subnet Drill
                    </div>
                    <div className="text-white/80">Monitor net nodes for PRISM corruption.</div>
                    <div className="text-emerald-400 font-bold">Reward: +200 ₡, +100 XP</div>
                  </div>

                  <div className="rounded-xl border border-white/10 bg-slate-950/60 p-2 space-y-1">
                    <div className="font-bold text-amber-300 flex items-center gap-1">
                      <Lock size={12} className="text-amber-400" /> Faith Medical Scan
                    </div>
                    <div className="text-white/80">Verify student aura health records.</div>
                    <div className="text-emerald-400 font-bold">Reward: +150 ₡, +75 XP</div>
                  </div>
                </div>
              </div>
            )}

            {screenApp === 'status' && (
              <div className="space-y-2 bg-slate-900/80 rounded-xl p-3 border border-cyan-400/30 text-xs font-mono">
                <div className="flex items-center justify-between border-b border-cyan-400/30 pb-1">
                  <button onClick={() => setScreenApp('home')} className="text-cyan-300 hover:text-white text-[10px] flex items-center gap-1">
                    <ChevronLeft size={14} /> Back
                  </button>
                  <span className="text-[10px] font-bold text-cyan-300">SYSTEM STATUS</span>
                  <div className="w-4" />
                </div>

                <div className="space-y-1.5 text-[10px]">
                  <div className="flex justify-between">
                    <span className="text-white/60">Level:</span>
                    <span className="font-bold text-emerald-400">Level {player.level}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-white/60">XP Progress:</span>
                    <span className="font-bold text-cyan-300">{player.xp} XP</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-white/60">Credits:</span>
                    <span className="font-bold text-emerald-400">₡{player.credits}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-white/60">Aura Health:</span>
                    <span className="font-bold text-purple-400">{player.auraHealth}%</span>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* ================================================================== */}
        {/* DEVICE MODE 2: VEIL-FOLD MULTI-PANE AETHER TABLET UNFOLDING          */}
        {/* ================================================================== */}
        {deviceMode === 'tablet' && (
          <div className="h-full grid grid-cols-3 gap-3.5 pt-1">
            {/* PANE 1: CYCADEMY MESSENGER LIVE FEED */}
            <div className="rounded-xl border border-cyan-400/40 bg-slate-900/90 p-3 flex flex-col justify-between shadow-[0_0_15px_rgba(77,243,255,0.2)]">
              <div className="flex items-center justify-between border-b border-cyan-400/30 pb-1.5 font-mono text-[10px]">
                <span className="font-bold text-cyan-300 flex items-center gap-1">
                  <LinkIcon size={12} /> Messenger
                </span>
                <span className="text-cyan-400/60">PANE 1</span>
              </div>

              <div className="flex gap-1 overflow-x-auto py-1 border-b border-white/10 text-[9px] font-mono">
                {Object.keys(npcMessages).map((npc) => (
                  <button
                    key={npc}
                    onClick={() => setActiveCommsContact(npc)}
                    className={`px-1.5 py-0.5 rounded transition ${
                      activeCommsContact === npc ? 'bg-cyan-500 text-slate-950 font-bold' : 'text-white/50'
                    }`}
                  >
                    {npc}
                  </button>
                ))}
              </div>

              <div className="flex-1 overflow-auto space-y-1.5 my-1.5 text-[9px] font-mono">
                {(npcMessages[activeCommsContact] || []).map((msg) => (
                  <div key={msg.id} className="rounded border border-white/10 bg-slate-950/60 p-1.5 space-y-0.5">
                    <div className="flex justify-between text-cyan-300 font-bold">
                      <span>{msg.isPlayer ? 'YOU' : activeCommsContact}</span>
                      <span className="text-white/40 text-[8px]">{msg.time}</span>
                    </div>
                    <div className="text-white/90">{msg.text}</div>
                  </div>
                ))}
              </div>

              <input
                type="text"
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={handleSendNpcMessage}
                placeholder="Reply to contact..."
                className="w-full rounded border border-cyan-400/40 bg-black/60 px-2 py-1 text-[10px] text-white outline-none font-mono"
              />
            </div>

            {/* PANE 2: LIVE DGA MISSION FEEDS & PULSE TRENDING */}
            <div className="rounded-xl border border-purple-400/40 bg-slate-900/90 p-3 flex flex-col justify-between shadow-[0_0_15px_rgba(192,132,252,0.2)] font-mono text-[10px]">
              <div className="flex items-center justify-between border-b border-purple-400/30 pb-1.5">
                <span className="font-bold text-purple-300 flex items-center gap-1">
                  <ShieldAlert size={12} /> DGA Missions
                </span>
                <span className="text-purple-400/60">PANE 2</span>
              </div>

              <div className="space-y-2 my-auto">
                <div className="rounded-lg border border-purple-400/30 bg-purple-950/40 p-2 space-y-1">
                  <div className="font-bold text-purple-300 flex items-center gap-1">
                    <Zap size={12} className="text-purple-400" /> Sector 7 Subnet Drill
                  </div>
                  <div className="text-white/80 text-[9px]">Monitor net nodes for PRISM corruption.</div>
                  <div className="text-emerald-400 font-bold text-[9px]">Reward: +200 ₡, +100 XP</div>
                </div>

                <div className="rounded-lg border border-purple-400/30 bg-white/5 p-2 space-y-1">
                  <div className="font-bold text-amber-300 flex items-center gap-1">
                    <Zap size={12} className="text-amber-400" /> Pulse Trending:
                  </div>
                  <div className="flex gap-1 text-[8px]">
                    <span className="rounded bg-purple-900/60 px-1.5 py-0.5 text-purple-300">#DormDrama</span>
                    <span className="rounded bg-cyan-900/60 px-1.5 py-0.5 text-cyan-300">#OddSighting</span>
                  </div>
                </div>
              </div>

              <div className="rounded bg-slate-950 border border-purple-400/30 p-1.5 text-[9px] text-purple-300 text-center">
                PRISM Corruption Level: {prismCorruptionLevel}%
              </div>
            </div>

            {/* PANE 3: SPELLFORGE RUNE SYNTHESIZER */}
            <div className="rounded-xl border border-violet-400/40 bg-slate-900/90 p-3 flex flex-col justify-between shadow-[0_0_15px_rgba(199,124,255,0.2)] font-mono text-[10px]">
              <div className="flex items-center justify-between border-b border-violet-400/30 pb-1.5">
                <span className="font-bold text-violet-300 flex items-center gap-1">
                  <Flame size={12} /> SpellForge
                </span>
                <span className="text-violet-400/60">PANE 3</span>
              </div>

              <div className="space-y-1.5 my-auto">
                <div>
                  <div className="text-white/50 text-[8px] mb-1">Element:</div>
                  <div className="grid grid-cols-3 gap-1">
                    {['Firewall', 'Cryo', 'Encryption'].map((el) => (
                      <button
                        key={el}
                        onClick={() => setSpellSelectedElement(el)}
                        className={`p-1 rounded text-[8px] border transition ${
                          spellSelectedElement === el
                            ? 'border-violet-400 bg-violet-500/30 text-white'
                            : 'border-white/10 bg-white/5 text-white/70'
                        }`}
                      >
                        {el}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <div className="text-white/50 text-[8px] mb-1">Utility:</div>
                  <div className="grid grid-cols-3 gap-1">
                    {['Routing', 'Anchor', 'Pulse'].map((ut) => (
                      <button
                        key={ut}
                        onClick={() => setSpellSelectedUtility(ut)}
                        className={`p-1 rounded text-[8px] border transition ${
                          spellSelectedUtility === ut
                            ? 'border-cyan-400 bg-cyan-500/30 text-white'
                            : 'border-white/10 bg-white/5 text-white/70'
                        }`}
                      >
                        {ut}
                      </button>
                    ))}
                  </div>
                </div>

                {spellResult && (
                  <div className="rounded bg-slate-950 border border-violet-400/40 p-1.5 text-violet-300 text-[8px]">
                    {spellResult}
                  </div>
                )}
              </div>

              <button
                onClick={handleSynthesizeSpell}
                className="w-full rounded border border-violet-400 bg-violet-500/20 py-1 font-bold text-violet-300 hover:bg-violet-500/40 transition text-[9px] flex items-center justify-center gap-1"
              >
                <Sparkles size={12} /> [ SYNTHESIZE RUNE ]
              </button>
            </div>
          </div>
        )}
      </div>
    </motion.div>
  );
}
